// Title: C# – Apply "MMMM dd, yyyy" custom date format to dates generated by Aspose.Cells Smart Markers
// Description: Demonstrates how to create a workbook template with smart markers for a Date and Description column, bind a List<Record> as the data source, process the markers with WorkbookDesigner, and then apply a Style with the custom format "MMMM dd, yyyy" to every populated date cell before saving the report.
// Keywords: Aspose.Cells | C# | .NET | Smart Markers | custom date format | MMMM dd, yyyy | WorkbookDesigner | date styling | dynamic report | Excel export
// Common Searches: Aspose.Cells format date smart marker C# | apply custom date style after WorkbookDesigner | set MMMM dd, yyyy format in generated Excel | C# smart marker date formatting example | how to style date column in Aspose.Cells report
// Developer Intent: Apply a long‑month custom format to all DateTime cells produced by smart markers in a .NET Excel report.
// Use Cases: Define smart markers for a date column, bind a collection of objects, and automatically format the resulting dates as "MMMM dd, yyyy". | Create a reusable Style with a custom date pattern and assign it only to cells whose type is DateTime after processing smart markers. | Generate a dynamic sales or audit report where the date column consistently displays the full month name regardless of row count.
// AI Prompts: Write C# code that uses Aspose.Cells WorkbookDesigner to bind a list of records, processes smart markers, and formats all date cells with "MMMM dd, yyyy". | Show how to iterate over the rows created by smart markers and apply a custom date style only to cells containing DateTime values. | Explain the steps to combine smart marker processing with post‑processing styling to ensure dates appear in a specific format in an Aspose.Cells generated workbook.

using System;
using System.Collections.Generic;
using Aspose.Cells;
using Aspose.Cells.Charts;

namespace AsposeCellsSmartMarkerDateFormat
{
    // Sample data class with a Date property
    // Demonstrates how to create a workbook template with smart markers for a Date and Description column, bind a List<Record> as the data source, process the markers with WorkbookDesigner, and then apply a Style with the custom format "MMMM dd, yyyy" to every populated date cell before saving the report.
    public class Record
    {
        public DateTime Date { get; set; }
        public string Description { get; set; }
    }

    class Program
    {
        static void Main()
        {
            // 1. Create a new workbook (template)
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];
            Cells cells = sheet.Cells;

            // 2. Set up smart markers in the template
            // Header row
            cells["A1"].PutValue("Date");
            cells["B1"].PutValue("Description");
            // Smart marker row (will be repeated for each data item)
            cells["A2"].PutValue("&=$Date");          // Smart marker for date
            cells["B2"].PutValue("&=$Description");   // Smart marker for description

            // 3. Prepare data source
            List<Record> data = new List<Record>
            {
                new Record { Date = new DateTime(2023, 1, 15), Description = "First" },
                new Record { Date = new DateTime(2023, 2, 20), Description = "Second" },
                new Record { Date = new DateTime(2023, 3, 25), Description = "Third" }
            };

            // 4. Create WorkbookDesigner, assign workbook and data source
            WorkbookDesigner designer = new WorkbookDesigner
            {
                Workbook = workbook
            };
            designer.SetDataSource("Data", data);

            // 5. Process smart markers (the range with markers is automatically detected)
            designer.Process();

            // 6. Apply custom date format "MMMM dd, yyyy" to all cells that contain dates
            // Determine the used range for the date column (A column, starting from row 2)
            int firstDataRow = 2; // zero‑based index (row 2 in Excel is index 1, but we start after header)
            int lastRow = sheet.Cells.MaxDataRow; // last row with data after processing

            // Create a style with the desired custom date format
            Style dateStyle = workbook.CreateStyle();
            dateStyle.Custom = "MMMM dd, yyyy";

            // Apply the style to the date column range
            for (int row = firstDataRow; row <= lastRow; row++)
            {
                Cell cell = cells[row, 0]; // Column A
                // Ensure the cell actually contains a DateTime value
                if (cell.Type == CellValueType.IsDateTime)
                {
                    cell.SetStyle(dateStyle);
                }
            }

            // 7. Save the resulting workbook
            workbook.Save("SmartMarkerDateFormattedReport.xlsx");
        }
    }
}
